import sympy

def find_solutions(max_b):
    solutions = []
    for b in range(1, max_b + 1):
        D = (2**(b+1) - 1)**2 - 8 * (3**b)
        if D < 0:
            continue
        sqrt_D = sympy.integer_nthroot(D, 2)
        if sqrt_D[1]:
            s_D = sqrt_D[0]
            term1 = 2**(b+1) - 1
            if (term1 + s_D) % 2 == 0:
                a1 = (term1 + s_D) // 2
                if a1 > 0:
                    solutions.append((a1, b))
            if (term1 - s_D) % 2 == 0:
                a2 = (term1 - s_D) // 2
                if a2 > 0:
                    solutions.append((a2, b))
    return solutions

sols = find_solutions(1000)
print("Solutions:", sols)
print("Sum of (a+b):", sum(a + b for a, b in sols))
